if(top&&top!==e&&!e.contains(top)&&!(top.contains&&top.contains(e))&&!(e.labels&&[...e.labels].some((l)=>l.contains(top))))return"covered by "+(top.id?"#"+top.id:top.className||top.tagName);return"reachable";};
